//! 🔺️ reorder-scenes leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfScene;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::reorder_scenes::mutation::{apply, validate, GltfReorderScenesPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{scenes_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-scenes.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderScenesOperation { Insert { position: usize, item: GltfScene }, Delete { index: usize, removed: GltfScene }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderScenesDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderScenesPayload, pub operation: GltfReorderScenesOperation }
fn operation(payload: &GltfReorderScenesPayload, base: &GltfSnapshot) -> GltfReorderScenesOperation { GltfReorderScenesOperation::Reorder { order: payload.order.clone() } }
fn touched_paths(payload: &GltfReorderScenesPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/scenes/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_diff(diff: &GltfReorderScenesDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfReorderScenesDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfReorderScenesOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Scenes, &Change::Insert(*position))?; next.document.scenes.insert(*position, item.clone());  }, GltfReorderScenesOperation::Delete { index, .. } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, None, None)?;  }, GltfReorderScenesOperation::Move { index, position } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, Some(*position), None)?;  }, GltfReorderScenesOperation::Reorder { order } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfReorderScenesDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfReorderScenesPayload, base: &GltfSnapshot) -> Result<GltfReorderScenesDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderScenesDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfReorderScenesPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Scenes, base, &next)) }
